    Object.assign(I18N.ru,{"routeLanguageText": "Семестр или год китайского: группы с нулевого уровня, кампусная жизнь и подготовка к следующему этапу.", "routeGrade9Text": "Старшая школа, пятилетний колледж или специальная pathway-программа — только если учреждение официально принимает аттестат 9 класса.", "routeGrade11Text": "Прямой бакалавриат, предвузовская подготовка или языковой год: выбираем путь по HSK, CSCA, английскому и специальности.", "routeMasterText": "Магистратура после бакалавриата: язык, академический профиль, рекомендации, план обучения или исследования и стипендии.", "routeSecondText": "Новая профессия после первого диплома: проверяем, нужен ли новый бакалавриат, возможна ли магистратура со сменой направления и зачтут ли дисциплины.", "showMatchingPrograms": "Показать подходящие программы в каталоге", "routeGuideLabel": "Практический гид", "routeGuideFacts": "Ключевые ориентиры"});
    Object.assign(I18N.en,{"routeLanguageText": "A semester or year of Chinese: beginner groups, campus life and preparation for the next academic step.", "routeGrade9Text": "Senior school, a five-year diploma route or a special pathway — only where the institution officially accepts a Grade 9 certificate.", "routeGrade11Text": "Direct bachelor’s entry, a pre-university programme or a language year — chosen around HSK, CSCA, English and the intended major.", "routeMasterText": "A master’s after a bachelor’s: language, academic fit, references, a study or research plan, interviews and scholarships.", "routeSecondText": "A new field after the first degree: check whether a new bachelor’s, a conversion-friendly master’s or credit recognition is realistic.", "showMatchingPrograms": "Show matching programmes in the catalogue", "routeGuideLabel": "Practical guide", "routeGuideFacts": "Key checkpoints"});
    Object.assign(I18N.kk,{"routeLanguageText": "Қытай тілінің бір семестрі немесе бір жылы: нөлден бастайтын топтар, кампус өмірі және келесі кезеңге дайындық.", "routeGrade9Text": "Жоғары сынып, бес жылдық колледж немесе арнайы pathway — оқу орны 9-сынып аттестатын ресми қабылдаған жағдайда ғана.", "routeGrade11Text": "Тікелей бакалавриат, университетке дейінгі дайындық немесе тілдік жыл — HSK, CSCA, ағылшын тілі мен мамандыққа қарай таңдалады.", "routeMasterText": "Бакалаврдан кейінгі магистратура: тіл, академиялық сәйкестік, ұсынымдар, оқу не зерттеу жоспары және стипендиялар.", "routeSecondText": "Бірінші дипломнан кейін жаңа бағыт: жаңа бакалавриат керек пе, басқа саладағы магистратура мүмкін бе және пәндер есептеле ме — тексереміз.", "showMatchingPrograms": "Каталогтан сәйкес бағдарламаларды көрсету", "routeGuideLabel": "Практикалық нұсқаулық", "routeGuideFacts": "Негізгі бағдарлар"});
    const TICKER_TEXTS={
      ru:['Международные связи','Университеты Китая','Современный кампус','Учись. Путешествуй. Расти.'],
      en:['International connections','Universities across China','Modern campus','Study. Travel. Grow.'],
      kk:['Халықаралық байланыстар','Қытай университеттері','Заманауи кампус','Оқы. Саяхатта. Өс.']
    };
    function updateLanguageDropdown(){
      const meta=LANGUAGE_META[state.lang]||LANGUAGE_META.ru;
      const flag=$('#sgCurrentLangFlag'),code=$('#sgCurrentLangCode');
      if(flag) flag.textContent=meta.flag;if(code) code.textContent=meta.code;
      $$('#sgLanguageMenu [data-lang]').forEach(btn=>{const active=btn.dataset.lang===state.lang;btn.classList.toggle('active',active);btn.setAttribute('aria-selected',String(active))});
    }
    function setupLanguageDropdown(){
      const wrap=$('#sgLanguage'),trigger=$('#sgLanguageTrigger'),menu=$('#sgLanguageMenu');
      if(!wrap||!trigger||!menu)return;
      trigger.addEventListener('click',e=>{e.stopPropagation();const open=wrap.classList.toggle('open');trigger.setAttribute('aria-expanded',String(open))});
      menu.querySelectorAll('[data-lang]').forEach(btn=>btn.addEventListener('click',()=>{state.lang=btn.dataset.lang;wrap.classList.remove('open');trigger.setAttribute('aria-expanded','false');applyTranslations()}));
      document.addEventListener('click',e=>{if(!wrap.contains(e.target)){wrap.classList.remove('open');trigger.setAttribute('aria-expanded','false')}});
      document.addEventListener('keydown',e=>{if(e.key==='Escape'){wrap.classList.remove('open');trigger.setAttribute('aria-expanded','false')}});
    }
    function renderTicker(){
      const track=$('#sgMarqueeTrack');if(!track)return;
      const items=TICKER_TEXTS[state.lang]||TICKER_TEXTS.ru;
      const group=items.map(text=>`<span class="sg-ref-marquee-item">${htmlSafe(text)}</span>`).join('');
      track.innerHTML=`<span class="sg-ref-marquee-group">${group}</span><span class="sg-ref-marquee-group" aria-hidden="true">${group}</span>`;
    }
    const ROUTE_IMAGES=["assets/images/embedded-11-0898a24734.jpg", "assets/images/embedded-12-8290b6c984.jpg", "assets/images/embedded-13-21bd8cdbd7.jpg", "assets/images/embedded-14-e0176ab81c.jpg", "assets/images/embedded-15-c2a1274026.jpg"];
    const ROUTE_IMAGE_OVERRIDES={
      3:'assets/images/embedded-16-b081e22608.jpg',
      4:'assets/images/embedded-17-bd772b098f.jpg'
    };
    function hydrateRouteImages(){
      $$('[data-route-image]').forEach(img=>{
        const index=Number(img.dataset.routeImage)||0;
        img.src=ROUTE_IMAGE_OVERRIDES[index]||ROUTE_IMAGES[index]||ROUTE_IMAGES[0];
        img.alt=[t('routeLanguageTitle'),t('routeGrade9Title'),t('routeGrade11Title'),t('routeMasterTitle'),t('routeSecondTitle')][index]||'StudyGo';
      });
      const credits=$('#routePhotoCredits');if(credits)credits.textContent=t('photoCredits');
    }
    function renderHeroInstitutionCount(){
      const statCount=$('#statInstitutionCount');if(!statCount)return;
      const value=String(institutions.length);
      statCount.setAttribute('aria-label',value);
      statCount.replaceChildren(...value.split('').map(digit=>{
        const item=document.createElement('span');
        item.className='sg-ref-count-digit';
        item.textContent=digit;
        return item;
      }));
    }

    function applyTranslations(){
      document.documentElement.lang=state.lang;
      $$('[data-i18n]').forEach(el=>{el.textContent=t(el.dataset.i18n)});
      $$('[data-i18n-html]').forEach(el=>{el.innerHTML=t(el.dataset.i18nHtml)});
      $$('[data-i18n-placeholder]').forEach(el=>{el.placeholder=t(el.dataset.i18nPlaceholder)});
      updateLanguageDropdown();
      renderTicker();
      document.title='StudyGo — '+t('navCatalog');
      buildFilters();
      buildSort();
      renderCatalog();
      updateFavoriteCount();
      renderHeroInstitutionCount();
      const openDetailId=$('#detailOverlay').dataset.id;
      if(openDetailId) openDetail(openDetailId,true);
      hydrateRouteImages();
      if(contentState)rerenderContent();
    }

    function uniq(values){return [...new Set(values)].sort((a,b)=>a.localeCompare(b));}
    function selectOptions(items,current,labelKey){return `<option value="">${t('all')}</option>`+items.map(item=>`<option value="${item.value}" ${current===item.value?'selected':''}>${item.label||t(item.key||item.value)}</option>`).join('')}
    function filterMarkup(prefix='f'){
      const cities=CHINA_EDUCATION_CITIES
        .map(item=>({value:item.value,label:item[state.lang]}))
        .sort((a,b)=>a.label.localeCompare(b.label));
      const selectedTypes=Array.isArray(state.type)?state.type:state.type?[state.type]:[];
      const selectedLevels=Array.isArray(state.levels)?state.levels:state.level?[state.level]:[];
      const selectedLanguages=Array.isArray(state.languages)?state.languages:state.language?[state.language]:[];
      const typeChecks=[['school','school'],['college','college'],['university','university']].map(([value,key])=>
        `<label class="type-check-card"><input type="checkbox" data-filter-type="${value}" ${selectedTypes.includes(value)?'checked':''}><span>${t(key)}</span></label>`
      ).join('');
      const levelChecks=[
        ['bachelor','bachelor'],['bachelor13','bachelor13'],['bachelor14','bachelor14'],['bachelor22','bachelor22'],
        ['foundation','foundation'],['doctorate','doctorate'],['longCourses','longCourses'],['winterCourses','winterCourses'],
        ['intensiveCourses','intensiveCourses'],['shortCourses','shortCourses'],['summerCourses','summerCourses'],
        ['master','master'],['secondary','secondary'],['secondary23','secondary23']
      ].map(([value,key])=>
        `<label class="type-check-card"><input type="checkbox" data-filter-level="${value}" ${selectedLevels.includes(value)?'checked':''}><span>${t(key)}</span></label>`
      ).join('');
      const languageChecks=[['chinese','chinese'],['english','english'],['russian','russian']].map(([value,key])=>
        `<label class="type-check-card"><input type="checkbox" data-filter-language="${value}" ${selectedLanguages.includes(value)?'checked':''}><span>${t(key)}</span></label>`
      ).join('');
      const specialtyItems=[
        ['business','business'],['economicsFinance','economicsFinance'],['internationalTrade','internationalTrade'],['management','management'],['accounting','accounting'],['marketing','marketing'],
        ['logistics','logistics'],['law','law'],['internationalRelations','internationalRelations'],
        ['chineseLanguage','chineseLanguage'],['foreignLanguages','foreignLanguages'],['languages','languages'],['educationSpec','educationSpec'],['psychology','psychology'],
        ['it','it'],['artificialIntelligence','artificialIntelligence'],['dataScience','dataScience'],['softwareEngineering','softwareEngineering'],
        ['engineering','engineering'],['mechanicalEngineering','mechanicalEngineering'],['electricalEngineering','electricalEngineering'],['civilEngineering','civilEngineering'],
        ['architecture','architecture'],['materials','materials'],['chemicalEngineering','chemicalEngineering'],
        ['medicine','medicine'],['dentistry','dentistry'],['pharmacy','pharmacy'],['nursing','nursing'],['publicHealth','publicHealth'],['tcm','tcm'],
        ['agriculture','agriculture'],['foodScience','foodScience'],['environment','environment'],['marineScience','marineScience'],
        ['aviation','aviation'],['transport','transport'],['tourism','tourism'],['hospitality','hospitality'],
        ['arts','arts'],['design','design'],['music','music'],['sports','sports'],['media','media'],
        ['science','science'],['mathematics','mathematics'],['physics','physics'],['chemistry','chemistry'],['biology','biology']
      ].map(([value,key])=>({value,key}));
      return `
        <div class="filter-group"><label class="filter-label">${t('country')}</label><select class="select filter-select-unified country-fixed-select" id="${prefix}-country" disabled><option selected>${t('china')}</option></select></div>
        <div class="filter-group"><label class="filter-label">${t('city')}</label><select class="select filter-select-unified" data-filter="city" id="${prefix}-city">${selectOptions(cities,state.city)}</select></div>
        <div class="filter-group"><label class="filter-label">${t('institutionType')}</label><div class="type-check-list">${typeChecks}</div></div>
        <div class="filter-group"><label class="filter-label">${t('programLevel')}</label><div class="program-level-list">${levelChecks}</div></div>
        <div class="filter-group"><label class="filter-label">${t('specialty')}</label><select class="select filter-select-unified" data-filter="specialty" id="${prefix}-specialty">${selectOptions(specialtyItems,state.specialty)}</select></div>
        <div class="filter-group"><label class="filter-label">${t('studyLanguage')}</label><div class="language-check-list">${languageChecks}</div></div>
        <div class="filter-group"><label class="filter-label">${t('hsk')}</label><select class="select filter-select-unified" data-filter="hsk" id="${prefix}-hsk">${selectOptions([{value:'noHsk',key:'noHsk'},{value:'hsk3',key:'hsk3'},{value:'hsk4',key:'hsk4'},{value:'hsk5',key:'hsk5'}],state.hsk)}</select></div>
        <div class="filter-group"><label class="filter-label">${t('education')}</label><select class="select filter-select-unified" data-filter="education" id="${prefix}-education">${selectOptions([{value:'grade9',key:'grade9'},{value:'grade11',key:'grade11'},{value:'bachelorDegree',key:'bachelorDegree'}],state.education)}</select></div>
        <div class="filter-group"><label class="filter-label">${t('maxTuition')}: <strong>${formatMoney(state.maxTuition)}</strong></label><div class="range-wrap"><input type="range" min="12000" max="50000" step="1000" value="${state.maxTuition}" data-filter="maxTuition"><div class="range-caption"><span>12 000</span><span>50 000 CNY</span></div></div></div>
        <div class="filter-group"><label class="filter-label">${t('extra')}</label>
          <div class="featured-switches">
            ${switchFilter('open','openFilter','open-switch')}
            ${switchFilter('partner','partnerFilter','partner-switch')}
          </div>
          <div class="check-list secondary-checks">
            ${check('scholarship','scholarshipFilter')}${check('dormitory','dormitoryFilter')}${check('minor','minorFilter')}
          </div>
        </div>`;
    }
    function switchFilter(key,label,extraClass=''){return `<label class="filter-switch ${extraClass}"><span>${t(label)}</span><input type="checkbox" data-filter="${key}" ${state[key]?'checked':''}><i class="filter-switch-track" aria-hidden="true"></i></label>`}
    function check(key,label){return `<label class="check-row"><input type="checkbox" data-filter="${key}" ${state[key]?'checked':''}><span>${t(label)}</span></label>`}
    function buildFilters(){
      $('#filterContent').innerHTML=filterMarkup('desk');
      $('#mobileFilterContent').innerHTML=filterMarkup('mob');
      bindFilterEvents();
    }
    function buildSort(){
      $('#sortSelect').innerHTML=[['recommended','sortRecommended'],['price','sortPrice'],['programs','sortPrograms'],['deadline','sortDeadline']].map(([v,k])=>`<option value="${v}" ${state.sort===v?'selected':''}>${t(k)}</option>`).join('');
    }
    function bindFilterEvents(){
      $$('[data-filter]').forEach(el=>{
        const evt=el.type==='range'?'input':'change';
        el.addEventListener(evt,()=>{
          const key=el.dataset.filter;
          state[key]=el.type==='checkbox'?el.checked:el.value;
          if(key==='maxTuition') state.maxTuition=Number(el.value);
          if(key==='province'){
            state.city='';
            state.page=1;
            buildFilters();
            renderCatalog();
            return;
          }
          state.page=1;
          syncFilterControls(key);
          renderCatalog();
        });
      });
      $$('[data-filter-type]').forEach(el=>el.addEventListener('change',()=>{
        const value=el.dataset.filterType;
        const set=new Set(Array.isArray(state.type)?state.type:[]);
        el.checked?set.add(value):set.delete(value);
        state.type=[...set];
        state.page=1;
        $$(`[data-filter-type="${value}"]`).forEach(peer=>peer.checked=el.checked);
        renderCatalog();
      }));
      $$('[data-filter-level]').forEach(el=>el.addEventListener('change',()=>{
        const value=el.dataset.filterLevel;
        const set=new Set(Array.isArray(state.levels)?state.levels:[]);
        el.checked?set.add(value):set.delete(value);
        state.levels=[...set];
        state.level='';
        state.page=1;
        $$(`[data-filter-level="${value}"]`).forEach(peer=>peer.checked=el.checked);
        renderCatalog();
      }));
      $$('[data-filter-language]').forEach(el=>el.addEventListener('change',()=>{
        const value=el.dataset.filterLanguage;
        const set=new Set(Array.isArray(state.languages)?state.languages:[]);
        el.checked?set.add(value):set.delete(value);
        state.languages=[...set];
        state.language='';
        state.page=1;
        $$(`[data-filter-language="${value}"]`).forEach(peer=>peer.checked=el.checked);
        renderCatalog();
      }));
    }
    function syncFilterControls(changed){
      $$(`[data-filter="${changed}"]`).forEach(el=>{
        if(el.type==='checkbox')el.checked=state[changed]; else el.value=state[changed];
      });
      if(changed==='maxTuition') buildFilters();
    }
    function matchInstitution(x){
      const q=state.query.trim().toLocaleLowerCase();
      const hay=[...Object.values(x.name),x.zh,...Object.values(x.city),...Object.values(x.province),...x.specialties.map(s=>t(s)),...x.programs.flatMap(p=>Object.values(p.name))].join(' ').toLocaleLowerCase();
      return (!q||hay.includes(q))&&(!state.city||x.city.en===state.city)&&(!(Array.isArray(state.type)&&state.type.length)||state.type.includes(x.type))&&(!state.education||x.education.includes(state.education))&&(!(Array.isArray(state.levels)&&state.levels.length)||state.levels.some(level=>x.levels.includes(level)))&&(!(Array.isArray(state.languages)&&state.languages.length)||state.languages.some(language=>x.languages.includes(language)))&&(!state.hsk||x.hsk.includes(state.hsk))&&(!state.specialty||x.specialties.includes(state.specialty))&&x.tuition<=state.maxTuition&&(!state.scholarship||x.scholarship)&&(!state.partner||x.partner)&&(!state.dormitory||x.dormitory)&&(!state.open||x.open)&&(!state.minor||x.minor);
    }
    function getRows(){
      const rows=institutions.filter(matchInstitution);
      if(state.sort==='price') rows.sort((a,b)=>a.tuition-b.tuition);
      if(state.sort==='programs') rows.sort((a,b)=>b.programCount-a.programCount);
      if(state.sort==='deadline') rows.sort((a,b)=>(a.deadline?new Date(a.deadline):Infinity)-(b.deadline?new Date(b.deadline):Infinity));
      if(state.sort==='recommended') rows.sort((a,b)=>(Number(b.partner)+Number(b.open)+Number(b.scholarship))-(Number(a.partner)+Number(a.open)+Number(a.scholarship)));
      return rows;
    }
    function activeFilterItems(){
      const provinceLabel=state.province?provinceName(state.province):'';
      const cityLabel=state.city?cityName(state.city):'';
      const typeLabel=Array.isArray(state.type)&&state.type.length?state.type.map(v=>t(v)).join(' · '):'';
      const levelsLabel=Array.isArray(state.levels)&&state.levels.length?state.levels.map(v=>t(v)).join(' · '):'';
      const languagesLabel=Array.isArray(state.languages)&&state.languages.length?state.languages.map(v=>t(v)).join(' · '):'';
      const map={province:provinceLabel,city:cityLabel,type:typeLabel,education:state.education&&t(state.education),levels:levelsLabel,languages:languagesLabel,hsk:state.hsk&&t(state.hsk),specialty:state.specialty&&t(state.specialty),scholarship:state.scholarship&&t('scholarshipFilter'),partner:state.partner&&t('partnerFilter'),dormitory:state.dormitory&&t('dormitoryFilter'),open:state.open&&t('openFilter'),minor:state.minor&&t('minorFilter')};
      return Object.entries(map).filter(([,v])=>v).map(([k,v])=>({key:k,label:v}));
    }
    function paginationItems(totalPages,current){
      if(totalPages<=7)return Array.from({length:totalPages},(_,i)=>i+1);
      const items=[1];
      if(current>4)items.push('…');
      const start=Math.max(2,current-1),end=Math.min(totalPages-1,current+1);
      for(let i=start;i<=end;i++)items.push(i);
      if(current<totalPages-3)items.push('…');
      items.push(totalPages);
      return items;
    }
    function renderPagination(totalRows){
      const totalPages=Math.max(1,Math.ceil(totalRows/state.pageSize));
      if(state.page>totalPages)state.page=totalPages;
      const nav=$('#catalogPagination');
      if(!nav)return;
      if(totalRows<=state.pageSize){nav.innerHTML='';nav.style.display='none';return}
      nav.style.display='flex';
      const numbers=paginationItems(totalPages,state.page).map(item=>item==='…'
        ?`<span class="page-ellipsis">…</span>`
        :`<button class="page-btn ${item===state.page?'active':''}" data-page="${item}" type="button" aria-current="${item===state.page?'page':'false'}">${item}</button>`).join('');
      nav.innerHTML=`<button class="page-btn page-nav" data-page="${state.page-1}" ${state.page===1?'disabled':''} type="button">← ${t('prevPage')}</button>${numbers}<button class="page-btn page-nav" data-page="${state.page+1}" ${state.page===totalPages?'disabled':''} type="button">${t('nextPage')} →</button>`;
      nav.querySelectorAll('[data-page]').forEach(btn=>btn.addEventListener('click',()=>{
        const page=Number(btn.dataset.page);
        if(!page||page<1||page>totalPages||page===state.page)return;
        state.page=page;renderCatalog();
        $('#catalog').scrollIntoView({behavior:'smooth',block:'start'});
      }));
    }
    function renderCatalog(){
      const rows=getRows();
      $('#resultCount').innerHTML=`${t('found')}: <strong>${rows.length}</strong> ${t('institutionsWord')}`;
      $('#activeChips').innerHTML=activeFilterItems().map(x=>`<button class="active-chip" data-clear="${x.key}">${x.label} ×</button>`).join('');
      $$('[data-clear]').forEach(btn=>btn.addEventListener('click',()=>{const k=btn.dataset.clear;state[k]=Array.isArray(state[k])?[]:(typeof state[k]==='boolean'?false:'');state.page=1;buildFilters();renderCatalog()}));
      const totalPages=Math.max(1,Math.ceil(rows.length/state.pageSize));
      if(state.page>totalPages)state.page=totalPages;
      const startIndex=(state.page-1)*state.pageSize;
      const visible=rows.slice(startIndex,startIndex+state.pageSize);
      $('#cards').innerHTML=visible.length?visible.map(cardMarkup).join(''):`<div class="empty"><strong>${t('noResults')}</strong><br><br><button class="soft-btn" data-action="reset">${t('reset')}</button></div>`;
      renderPagination(rows.length);
      bindCardEvents();
      updateCompareBar();
    }
    function cardMarkup(x){
      const tuitionText=x.tuition>0?`${formatMoney(x.tuition)} / ${t('perYear')}`:t('toConfirm');
      const ageText=x.minAge?`${t('from')} ${x.minAge} ${t('years')}`:t('byProgram');
      const programText=x.programCount>0?x.programCount:t('toConfirm');
      const deadlineText=x.deadline?formatDate(x.deadline):t('toConfirm');
      const photoLabel=x.photoSource==='studygo'?t('photoStudyGo'):(x.photoSource==='official'?t('photoOfficial'):(x.photoSource==='file'?t('photoFile'):t('photoSearch')));
      return `<article class="uni-card">
        <div class="uni-media">
          <img class="uni-media-img" src="${x.image}" alt="${htmlSafe(nameOf(x.name))}" loading="lazy" onerror="this.onerror=null;this.src='${x.fallbackImage||''}'">
          <div class="uni-media-shade"></div>
          <div class="photo-source-label">${photoLabel}</div>
          <div class="media-top"><div class="badges">${x.partner?`<span class="badge partner">✦ ${t('partnerBadge')}</span>`:''}${x.scholarship?`<span class="badge grant">● ${t('grantBadge')}</span>`:''}${x.open?`<span class="badge open">● ${t('openBadge')}</span>`:''}${x.sourceType==='sovian'?`<span class="badge registry">SOVIAN</span>`:''}${x.sourceType==='public-catalog'?`<span class="badge registry">База 325</span>`:''}</div><button class="icon-btn ${favorites.has(x.id)?'active':''}" data-favorite="${x.id}" aria-label="Favorite">${favorites.has(x.id)?'♥':'♡'}</button></div>
          <div class="media-bottom"><div class="location">${nameOf(x.city)}, ${nameOf(x.province)}<small>${nameOf(x.district)}</small></div><div class="verified">✓ ${t('verified')}: ${x.updated}</div></div>
        </div>
        <div class="uni-body"><h3 class="uni-title">${nameOf(x.name)}</h3><p class="uni-zh">${x.zh}</p>
          <div class="uni-tags"><span class="tag purple">${t(x.type)}</span><span class="tag">${t(x.ownership)}</span>${x.education.includes('grade9')?`<span class="tag mint">${t('after9')}</span>`:''}${x.hsk.includes('noHsk')?`<span class="tag">${t('noHsk')}</span>`:''}</div>
          <p class="uni-description">${htmlSafe((x.description&&x.description[state.lang])||x.description?.ru||'')}</p>
          <div class="uni-grid"><div class="uni-fact"><span>${t('tuitionFrom')}</span><strong>${tuitionText}</strong></div><div class="uni-fact"><span>${t('ageFrom')}</span><strong>${ageText}</strong></div><div class="uni-fact"><span>${t('programsWord')}</span><strong>${programText}</strong></div><div class="uni-fact"><span>${t('deadline')}</span><strong>${deadlineText}</strong></div></div>
          <div class="uni-actions"><button class="details-btn" data-detail="${x.id}">${t('details')}</button><button class="compare-btn ${compare.has(x.id)?'active':''}" data-compare="${x.id}">${compare.has(x.id)?'✓ ':''}${compare.has(x.id)?t('compareAdded'):t('compareAdd')}</button></div>
        </div></article>`;
    }
    function bindCardEvents(){
      $$('[data-detail]').forEach(b=>b.addEventListener('click',()=>openDetail(b.dataset.detail)));
      $$('[data-favorite]').forEach(b=>b.addEventListener('click',()=>toggleFavorite(b.dataset.favorite)));
      $$('[data-compare]').forEach(b=>b.addEventListener('click',()=>toggleCompare(b.dataset.compare)));
      $$('[data-action="reset"]').forEach(b=>b.addEventListener('click',resetFilters));
    }
    function formatDate(s){if(!s)return t('toConfirm');const d=new Date(s+'T00:00:00');return Number.isNaN(d.getTime())?t('toConfirm'):new Intl.DateTimeFormat(state.lang==='en'?'en-GB':state.lang==='kk'?'kk-KZ':'ru-RU',{day:'2-digit',month:'short',year:'numeric'}).format(d)}
    function toggleFavorite(id){favorites.has(id)?favorites.delete(id):favorites.add(id);safeStorage.setItem('studygoFavorites',JSON.stringify([...favorites]));updateFavoriteCount();renderCatalog();showToast(t('favoritesToast'))}
    function updateFavoriteCount(){$('#favCount').textContent=favorites.size}
    function toggleCompare(id){compare.has(id)?compare.delete(id):(compare.size<3?compare.add(id):showToast('Max 3'));renderCatalog()}
    function updateCompareBar(){const el=$('#compareBar');el.classList.toggle('show',compare.size>0);$('#compareText').textContent=`${t('compareSelected')}: ${compare.size}/3`}
    function resetFilters(){Object.assign(state,{query:'',province:'',city:'',type:[],education:'',level:'',levels:[],language:'',languages:[],hsk:'',specialty:'',age:'',maxTuition:50000,scholarship:false,partner:false,dormitory:false,open:false,minor:false,page:1});$('#catalogSearch').value='';const hs=$('#heroSearch');if(hs)hs.value='';buildFilters();renderCatalog()}

    function registryLinksMarkup(x){
      if(!x.registry)return'';
      const links=[
        [t('officialSite'),safeExternalUrl(x.registry.officialUrl)],
        [t('admissionPage'),safeExternalUrl(x.registry.admissionsUrl)],
        [t('ministrySource'),safeExternalUrl(x.registry.ministryUrl)]
      ].filter(([,url])=>url);
      return links.length?`<div class="registry-links">${links.map(([label,url])=>`<a href="${htmlSafe(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`).join('')}</div>`:'';
    }
    function registryOverviewMarkup(x){
      if(!x.registry)return'';
      const r=x.registry;
      const cards=[
        registryInfoCard(t('registryProfile'),registryValue(x,'profile')||registryValue(x,'preliminarySpecialization')),
        registryInfoCard(t('registryDirections'),registryValue(x,'directions')),
        registryInfoCard(t('registryFormats'),registryValue(x,'formats')),
        registryInfoCard(t('registryEducation'),registryValue(x,'educationRequirement')),
        registryInfoCard(t('registryAge'),registryValue(x,'ageNotes')),
        registryInfoCard(t('registryAddress'),registryValue(x,'address')||registryValue(x,'allCities')),
        registryInfoCard(t('registryContacts'),[r.email,r.phone,r.contactPerson].filter(Boolean).map(htmlSafe).join('<br>'))
      ].filter(Boolean).join('');
      const sourceDescription=r.sourceDescription?`<div class="registry-source-copy"><h4>${t('registryDescription')}</h4><p>${htmlSafe(r.sourceDescription).replace(/\n/g,'<br>')}</p></div>`:'';
      return `<div class="registry-panel"><div class="registry-panel-head"><div><span class="registry-kicker">${t('registrySource')}</span><h4>${t('sourceInRussian')}</h4></div><strong>${t('registryUpdated')}: ${htmlSafe(r.verified||x.updated)}</strong></div><div class="registry-info-grid">${cards}</div>${sourceDescription}${registryLinksMarkup(x)}</div>`;
    }
    function routeInfoMarkup(x){
      if(!x.registry)return'';
      return `<div class="registry-info-grid route-registry-grid">
        ${registryInfoCard(t('registryRoute9'),registryValue(x,'route9'))}
        ${registryInfoCard(t('registryRoute11'),registryValue(x,'route11'))}
        ${registryInfoCard(t('registryEducation'),registryValue(x,'educationRequirement'))}
        ${registryInfoCard(t('registryAge'),registryValue(x,'ageNotes'))}
      </div>`;
    }
    function localText(ru,en,kk){return state.lang==='en'?en:(state.lang==='kk'?kk:ru)}
    function detailMarkup(x){
      const educationText=x.education&&x.education.length?x.education.map(v=>t(v)).join(', '):t('toConfirm');
      const hskText=x.hsk&&x.hsk.length?x.hsk.map(v=>t(v)).join(', '):t('toConfirm');
      const programsHtml=x.programs&&x.programs.length?x.programs.map(programMarkup).join(''):`<div class="registry-empty-programs"><strong>${t('registryNoPrograms')}</strong><p>${t('registryProgramsPending')}</p>${x.registry?.directions?`<p><b>${t('registryDirections')}:</b> ${htmlSafe(x.registry.directions)}</p>`:''}${x.registry?.formats?`<p><b>${t('registryFormats')}:</b> ${htmlSafe(x.registry.formats)}</p>`:''}</div>`;
      const notice=x.sourceType==='sovian'?t('sourceDataNote'):(x.sourceType==='official-curated'?t('officialCuratedNotice'):t('demoNotice'));
      const tuitionText=x.tuition>0?formatMoney(x.tuition):t('toConfirm');
      const foundedText=valueOrUnknown(x.founded);
      const official=safeExternalUrl(x.officialUrl||x.registry?.officialUrl);
      const admissions=safeExternalUrl(x.admissionsUrl||x.registry?.admissionsUrl);
      const description=htmlSafe((x.description&&x.description[state.lang])||x.description?.ru||'');
      const longCopy=(x.aboutLong?.[state.lang]||x.aboutLong?.ru||[]).map(p=>`<p>${htmlSafe(p)}</p>`).join('');
      const campusLife=htmlSafe((x.campusLife&&x.campusLife[state.lang])||x.campusLife?.ru||localText('Информация о повседневной жизни и инфраструктуре кампуса уточняется.','Campus life and infrastructure details are being verified.','Кампус өмірі мен инфрақұрылымы туралы ақпарат нақтылануда.'));
      const sports=htmlSafe((x.sports&&x.sports[state.lang])||x.sports?.ru||localText('Спортивные объекты и студенческие клубы уточняются для конкретного кампуса.','Sports facilities and student clubs are being verified for the specific campus.','Спорт нысандары мен студенттік клубтар нақты кампус бойынша тексерілуде.'));
      const cityGuide=htmlSafe((x.cityGuide&&x.cityGuide[state.lang])||x.cityGuide?.ru||`${nameOf(x.city)} — ${nameOf(x.province)}. ${localText('Подробный городской гид готовится.','A detailed city guide is being prepared.','Қала туралы толық гид дайындалуда.')}`);
      const gallery=(x.gallery&&x.gallery.length?x.gallery:[x.image,x.fallbackImage].filter(Boolean)).slice(0,5);
      const cityStats=(x.cityStats&&x.cityStats.length?x.cityStats:[[localText('Город','City','Қала'),nameOf(x.city)],[localText('Провинция','Province','Провинция'),nameOf(x.province)],[localText('Безопасность','Safety','Қауіпсіздік'),t('toConfirm')],[localText('Стоимость жизни','Cost of living','Өмір сүру құны'),t('toConfirm')]]);
      const campusTitle=x.registry?.allCities||nameOf(x.district);
      const countryRank=x.rankCountry||t('toConfirm'),worldRank=x.rankWorld||t('toConfirm');
      const servicePrice=x.servicePrice||localText('После бесплатной консультации','After a free consultation','Тегін кеңестен кейін');
      return `<div class="detail-cover" style="background-image:linear-gradient(135deg,rgba(20,15,45,.18),rgba(20,15,45,.32)),url('${x.image}')"><button class="detail-close" type="button" id="detailClose">✕</button><div class="detail-head"><div><div class="badges">${x.partner?`<span class="badge partner">✦ ${t('partnerBadge')}</span>`:''}${x.scholarship?`<span class="badge grant">● ${t('grantBadge')}</span>`:''}${x.sourceType==='sovian'?`<span class="badge registry">SOVIAN Education</span>`:''}</div><h2>${nameOf(x.name)}</h2><p>${x.zh}${x.name?.en?` · ${htmlSafe(x.name.en)}`:''}<br>${nameOf(x.city)}, ${nameOf(x.province)}</p></div><div class="detail-head-actions"><button data-detail-fav="${x.id}">${favorites.has(x.id)?'♥ '+t('saved'):'♡ '+t('save')}</button><button class="primary-btn" data-action="consult">${t('consult')}</button></div></div></div>
      <div class="detail-service-bar"><div><strong>${localText('Сопровождение поступления','Admissions support','Оқуға түсуге қолдау')}</strong><small>${localText('Подбор, проверка требований, документы и контроль сроков','Matching, requirement checks, documents and timeline control','Бағдарлама таңдау, талаптарды тексеру, құжаттар және мерзімдер')}</small></div><div><small>${localText('Стоимость услуги','Service price','Қызмет құны')}</small><div class="detail-service-price">${servicePrice}</div></div><button data-action="consult">${localText('Бесплатная консультация','Free consultation','Тегін кеңес')}</button></div>
      <nav class="detail-tabs">${[['overview','overview'],['programs','programsTab'],['admission','admission'],['costs','costs'],['grants','grants'],['campus','campus'],['city','city'],['gallery','gallery'],['documents','docsTitle'],['faq','faqTab']].map(([id,k],i)=>`<button data-tab="${id}" class="${i===0?'active':''}">${t(k)||k}</button>`).join('')}</nav>
      <div class="detail-content"><div class="demo-notice">⚠ ${notice}</div>
        <section class="detail-section" id="detail-overview"><h3>${t('overview')}</h3><p class="detail-section-lead">${description}</p>
          <div class="detail-fact-grid">
            <div class="detail-fact-item"><span>${localText('Страна','Country','Ел')}</span><strong>${localText('Китай','China','Қытай')}</strong></div><div class="detail-fact-item"><span>${t('city')}</span><strong>${nameOf(x.city)}</strong></div><div class="detail-fact-item"><span>${t('officialSite')}</span>${official?`<a href="${official}" target="_blank" rel="noopener">${localText('Открыть сайт ↗','Open website ↗','Сайтты ашу ↗')}</a>`:`<strong>${t('toConfirm')}</strong>`}</div><div class="detail-fact-item"><span>${t('institutionType')}</span><strong>${t(x.type)} · ${t(x.ownership)}</strong></div>
            <div class="detail-fact-item"><span>${localText('Гранты и стипендии','Scholarships','Гранттар')}</span><strong>${x.scholarship?localText('Есть варианты','Available','Бар'):localText('Не подтверждены','Not confirmed','Расталмаған')}</strong></div><div class="detail-fact-item"><span>${t('partnerFilter')}</span><strong>${x.partner?localText('Да','Yes','Иә'):localText('Нет','No','Жоқ')}</strong></div><div class="detail-fact-item"><span>${localText('Ранг в стране','Country rank','Елдегі рейтинг')}</span><strong>${countryRank}</strong></div><div class="detail-fact-item"><span>${localText('Ранг в мире','World rank','Әлемдік рейтинг')}</span><strong>${worldRank}</strong></div>
          </div>
          <div class="detail-stats"><div class="detail-stat"><span>${t('founded')}</span><strong>${foundedText}</strong></div><div class="detail-stat"><span>${t('students')}</span><strong>${valueOrUnknown(x.students)}</strong></div><div class="detail-stat"><span>${t('international')}</span><strong>${valueOrUnknown(x.international)}</strong></div><div class="detail-stat"><span>${t('campusesCount')}</span><strong>${valueOrUnknown(x.campuses)}</strong></div></div>
          <div class="detail-rich-copy">${longCopy||registryOverviewMarkup(x)}</div>
          <div class="fit-grid"><div class="fit-card yes"><h4>✓ ${t('suitable')}</h4><ul><li>${educationText}</li><li>${x.languages&&x.languages.length?x.languages.map(v=>t(v)).join(', '):t('toConfirm')}</li><li>HSK: ${hskText}</li><li>${x.dormitory?localText('Есть сведения об общежитии','Dormitory information is available','Жатақхана туралы ақпарат бар'):t('toConfirm')}</li></ul></div><div class="fit-card no"><h4>! ${localText('Что проверить до подачи','Check before applying','Өтінімге дейін тексеру')}</h4><ul><li>${localText('Актуальный список программ для иностранцев','Current international program list','Шетелдіктерге арналған бағдарламалар')}</li><li>${localText('Языковой сертификат и экзамены','Language certificates and exams','Тіл сертификаты және емтихандар')}</li><li>${localText('Дедлайн университета и гранта','University and scholarship deadlines','Университет пен грант мерзімдері')}</li><li>${localText('Свободные места в общежитии','Dormitory availability','Жатақхана орындары')}</li></ul></div></div>
        </section>
        <section class="detail-section" id="detail-programs"><h3>${localText('Программы, направления и сроки поступления','Programs, fields and intakes','Бағдарламалар, бағыттар және қабылдау мерзімдері')}</h3><p class="detail-section-lead">${localText('Выберите уровень и конкретную программу. Требования и стоимость должны проверяться для выбранного набора, а не только для университета в целом.','Choose a level and specific program. Requirements and fees must be checked for the selected intake, not only for the university as a whole.','Деңгей мен нақты бағдарламаны таңдаңыз. Талаптар мен құн нақты қабылдау кезеңі бойынша тексеріледі.')}</p><div class="program-list">${programsHtml}</div></section>
        <section class="detail-section" id="detail-admission"><h3>${t('admission')}</h3><p class="detail-section-lead">${t('requirements')}: ${educationText} · HSK: ${hskText}.</p>${routeInfoMarkup(x)}<div class="detail-subgrid"><div class="detail-story-card"><h4>${localText('Перед подачей','Before applying','Өтінімге дейін')}</h4><p>${localText('Проверяем право на программу, язык, возрастные ограничения, экзамены, формат перевода документов и отдельный дедлайн стипендии.','We verify eligibility, language, age rules, exams, document translation format and the separate scholarship deadline.','Бағдарламаға сәйкестік, тіл, жас шектеулері, емтихандар, аударма форматы және грант мерзімі тексеріледі.')}</p></div><div class="detail-story-card"><h4>${localText('После подачи','After applying','Өтінімнен кейін')}</h4><p>${localText('Отслеживаем проверку, запросы университета, интервью, оплату регистрационного сбора и выпуск визовых документов.','We track the review, university requests, interview, application fee and visa documents.','Тексеру, университет сұраулары, сұхбат, тіркеу төлемі және виза құжаттары бақыланады.')}</p></div></div></section>
        <section class="detail-section" id="detail-costs"><h3>${t('costTitle')}</h3><div class="cost-grid"><div class="info-card"><div class="icon">¥</div><h4>${t('price')}</h4><p>${x.tuition>0?localText('Стоимость из заполненных сведений; перепроверьте её для актуального набора.','Price from available data; verify it for the current intake.','Қолжетімді дерек бойынша құн; ағымдағы қабылдау үшін тексеріңіз.'):localText('Официальный прайс текущего набора запрашивается отдельно.','The official fee schedule for the current intake must be requested.','Ағымдағы қабылдаудың ресми бағасы бөлек сұралады.')}</p><strong class="price">${tuitionText}</strong></div><div class="info-card"><div class="icon">⌂</div><h4>${t('dormitories')}</h4><p>${x.dormitory?localText('Наличие проживания указано, но тип комнаты, цена и гарантия места уточняются.','Accommodation is mentioned, but room type, price and availability must be confirmed.','Жатақхана көрсетілген, бірақ бөлме, баға және орын кепілдігі нақтыланады.'):t('toConfirm')}</p></div><div class="info-card"><div class="icon">＋</div><h4>${localText('Дополнительные расходы','Additional costs','Қосымша шығындар')}</h4><p>${localText('Страховка, медосмотр, ВНЖ, книги, депозит и повседневные расходы.','Insurance, medical exam, residence permit, books, deposit and living costs.','Сақтандыру, медтексеру, тұруға рұқсат, кітаптар, депозит және күнделікті шығындар.')}</p></div></div></section>
        <section class="detail-section" id="detail-grants"><h3>${t('grantTitle')}</h3><div class="grant-grid"><div class="info-card ${x.scholarship?'green':''}"><div class="icon">★</div><h4>${t('scholarship')}</h4><p>${x.scholarship?localText('Есть упоминание стипендий. Проверяем покрытие, квоту, требования и условия продления для конкретной программы.','Scholarships are mentioned. Coverage, quota, requirements and renewal rules must be checked for the specific program.','Стипендия бар. Қамту, квота, талаптар және ұзарту шарттары нақты бағдарлама бойынша тексеріледі.'):localText('Стипендия для иностранных студентов в доступных данных не подтверждена.','An international student scholarship is not confirmed in the available data.','Шетелдік студенттерге стипендия қолжетімді деректе расталмаған.')}</p></div><div class="info-card orange"><div class="icon">!</div><h4>${localText('Важно','Important','Маңызды')}</h4><p>${localText('HSK для поступления и HSK для стипендии могут отличаться. Дедлайн гранта часто раньше основного дедлайна.','Admission and scholarship HSK requirements may differ. Scholarship deadlines are often earlier.','Қабылдау және стипендия HSK талаптары әртүрлі болуы мүмкін. Грант мерзімі жиі ертерек.')}</p></div></div></section>
        <section class="detail-section" id="detail-campus"><h3>${t('campusTitle')}</h3><div class="detail-subgrid"><div class="detail-story-card"><h4>${localText('Жизнь на кампусе','Campus life','Кампус өмірі')}</h4><p>${campusLife}</p></div><div class="detail-story-card"><h4>${localText('Спорт и активности','Sport and activities','Спорт және белсенділік')}</h4><p>${sports}</p></div></div><div class="campus-grid"><div class="info-card"><div class="icon">⌖</div><h4>${htmlSafe(campusTitle)}</h4><p>${x.registry?.address?htmlSafe(x.registry.address):`${nameOf(x.city)}, ${nameOf(x.province)}. ${t('toConfirm')}`}</p></div><div class="info-card"><div class="icon">⌂</div><h4>${t('dormitories')}</h4><p>${x.dormitory?localText('Наличие подтверждается исходными сведениями; детали запрашиваются отдельно.','Availability is mentioned; details must be requested.','Бар екені көрсетілген; толық мәлімет бөлек сұралады.'):t('toConfirm')}</p></div><div class="info-card"><div class="icon">↗</div><h4>${t('officialSite')}</h4>${registryLinksMarkup(x)||`<p>${t('toConfirm')}</p>`}</div></div></section>
        <section class="detail-section" id="detail-city"><h3>${localText('О городе','About the city','Қала туралы')}</h3><p class="detail-section-lead">${cityGuide}</p><div class="detail-city-stats">${cityStats.map(([a,b])=>`<div><span>${htmlSafe(a)}</span><b>${htmlSafe(b)}</b></div>`).join('')}</div></section>
        <section class="detail-section" id="detail-gallery"><h3>${localText('Фотографии и материалы','Photos and media','Фотосуреттер мен материалдар')}</h3><p class="detail-section-lead">${localText('Изображения из официальных источников и базы требуют финальной визуальной проверки перед публикацией.','Images from official sources and the database require a final visual check before publication.','Ресми дереккөздер мен базадағы суреттер жарияланар алдында тексерілуі керек.')}</p><div class="detail-gallery">${gallery.map((img,i)=>`<figure><img src="${img}" alt="${htmlSafe(nameOf(x.name))} — ${i+1}" loading="lazy" onerror="this.closest('figure').style.display='none'"></figure>`).join('')}</div></section>
        <section class="detail-section" id="detail-documents"><h3>${t('docsTitle')}</h3><div class="detail-docs-accordion"><details open><summary>${localText('Основной пакет документов','Core document package','Негізгі құжаттар')}</summary><div class="docs">${['Паспорт','Аттестат или диплом','Приложение с оценками','Перевод документов','Медицинская форма','Справка об отсутствии судимости','Языковой сертификат','Мотивационное письмо'].map(v=>`<div class="doc"><i>✓</i><span>${v}</span></div>`).join('')}</div></details><details><summary>${localText('Дополнительные документы','Additional documents','Қосымша құжаттар')}</summary><div class="docs">${['Рекомендательные письма','Study plan / research proposal','Финансовая гарантия','Согласие родителей и документы опекуна — для несовершеннолетних','Портфолио — если требуется'].map(v=>`<div class="doc"><i>+</i><span>${v}</span></div>`).join('')}</div></details></div></section>
        <section class="detail-section" id="detail-faq"><h3>${t('faqTitle')}</h3><div class="faq">${[
          [localText('Можно ли поступить после 9 класса?','Can I apply after Grade 9?','9-сыныптан кейін түсуге бола ма?'),x.education?.includes('grade9')?localText('В базе есть маршрут после 9 класса, но нужно подтвердить конкретную программу, возраст и опекунство.','A Grade 9 route is listed, but the specific program, age and guardian rules must be confirmed.','9-сыныптан кейінгі маршрут бар, бірақ бағдарлама, жас және қамқоршы талаптары тексеріледі.'):localText('В доступных данных маршрут после 9 класса не подтверждён.','A Grade 9 route is not confirmed in the available data.','9-сыныптан кейінгі маршрут расталмаған.')],
          [localText('Нужен ли HSK?','Is HSK required?','HSK керек пе?'),`HSK: ${hskText}. ${localText('Точный уровень зависит от программы и языка обучения.','The exact level depends on the program and teaching language.','Нақты деңгей бағдарлама мен оқу тіліне байланысты.')}`],
          [localText('Есть ли общежитие?','Is accommodation available?','Жатақхана бар ма?'),x.dormitory?localText('Общежитие упоминается, но наличие места, тип комнаты и стоимость нужно подтвердить.','Accommodation is mentioned, but availability, room type and price must be confirmed.','Жатақхана көрсетілген, бірақ орын, бөлме түрі және баға тексеріледі.'):t('toConfirm')],
          [localText('Когда заканчивается приём?','When is the deadline?','Қабылдау қашан аяқталады?'),x.deadline?formatDate(x.deadline):localText('Дедлайн текущего набора уточняется по официальной странице приёма.','The current intake deadline must be checked on the official admissions page.','Ағымдағы қабылдау мерзімі ресми парақтан тексеріледі.')]
        ].map(([q,a])=>`<div class="faq-item"><button class="faq-q"><span>${q}</span><span>＋</span></button><div class="faq-a">${a}</div></div>`).join('')}</div>
        <div class="detail-contact-card"><div><strong>${localText('Нужна проверка именно вашей ситуации?','Need your case checked?','Өз жағдайыңызды тексеру керек пе?')}</strong><p>${localText('Укажите образование, возраст, язык и желаемый набор — мы проверим доступные программы и спорные требования.','Share your education, age, language and intake — we will verify suitable programs and unclear requirements.','Біліміңізді, жасыңызды, тілді және қабылдау кезеңін көрсетіңіз — бағдарламалар мен талаптарды тексереміз.')}</p></div><button data-action="consult">${localText('Получить консультацию','Get consultation','Кеңес алу')}</button></div></section>
      </div>`;
    }
    function programMarkup(p){
      const priceText=p.price>0?formatMoney(p.price):t('toConfirm');
      const deadlineText=p.deadline||t('toConfirm');
      return `<article class="program-card"><div class="program-card-top"><div><h4>${nameOf(p.name)}</h4><p>${t(p.level)} · ${p.duration||t('toConfirm')}</p></div><span class="program-badge">${p.grant||t('toConfirm')}</span></div><div class="program-facts"><div class="program-fact"><span>${t('language')}</span><strong>${p.language?t(p.language):t('toConfirm')}</strong></div><div class="program-fact"><span>${t('educationReq')}</span><strong>${p.education?t(p.education):t('toConfirm')}</strong></div><div class="program-fact"><span>HSK</span><strong>${p.hsk?t(p.hsk):t('toConfirm')}</strong></div><div class="program-fact"><span>${t('price')}</span><strong>${priceText}</strong></div><div class="program-fact"><span>${t('deadline')}</span><strong>${deadlineText}</strong></div></div><div class="program-actions"><button data-program>${t('viewProgram')}</button></div></article>`;
    }
    function openDetail(id,rerender=false){
      const x=institutions.find(v=>v.id===id);if(!x)return;
      $('#detailOverlay').dataset.id=id;$('#detailShell').innerHTML=detailMarkup(x);$('#detailOverlay').classList.add('show');syncModalBody();
      if(!rerender) $('#detailOverlay').scrollTop=0;
      $('#detailClose').addEventListener('click',closeDetail);
      $('[data-detail-fav]').addEventListener('click',()=>{toggleFavorite(id);openDetail(id,true)});
      $$('#detailShell [data-action="consult"]').forEach(b=>b.addEventListener('click',openConsult));
      $$('#detailShell [data-program]').forEach((b,index)=>b.addEventListener('click',()=>openProgram(x,index)));
      $$('#detailShell [data-tab]').forEach(b=>b.addEventListener('click',()=>{const target=$('#detail-'+b.dataset.tab);if(target)target.scrollIntoView({behavior:'smooth',block:'start'});$$('#detailShell [data-tab]').forEach(v=>v.classList.remove('active'));b.classList.add('active')}));
      $$('#detailShell .faq-q').forEach(b=>b.addEventListener('click',()=>b.parentElement.classList.toggle('open')));
    }
    function closeDetail(){$('#detailOverlay').classList.remove('show');$('#detailOverlay').dataset.id='';syncModalBody()}
    function showToast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.remove('show'),2600)}

    function openProgram(institution,index){
      const program=institution.programs?.[index];
      if(!program)return;
      const price=program.price>0?formatMoney(program.price):t('toConfirm');
      openContent(`<button class="content-close" type="button" aria-label="${t('close')}">✕</button><div class="modal-panel program-modal-panel">
        <div class="sg-eyebrow">${t('programsTab')}</div><h2>${nameOf(program.name)}</h2><p>${nameOf(institution.name)} · ${nameOf(institution.city)}</p>
        <div class="program-modal-grid"><div><span>${t('duration')}</span><strong>${program.duration||t('toConfirm')}</strong></div><div><span>${t('language')}</span><strong>${program.language?t(program.language):t('toConfirm')}</strong></div><div><span>${t('educationReq')}</span><strong>${program.education?t(program.education):t('toConfirm')}</strong></div><div><span>HSK</span><strong>${program.hsk?t(program.hsk):t('toConfirm')}</strong></div><div><span>${t('price')}</span><strong>${price}</strong></div><div><span>${t('deadline')}</span><strong>${program.deadline||t('toConfirm')}</strong></div></div>
        <div class="article-note"><strong>${t('articleImportant')}:</strong> Требования относятся к конкретной программе и набору. Перед подачей мы повторно проверяем официальный источник.</div>
        <button class="consult-submit" data-action="consult" type="button">${t('consult')}</button>
      </div>`,{type:'program',institutionId:institution.id,index});
      $('#contentModal [data-action="consult"]')?.addEventListener('click',openConsult);
    }

    function compareMarkup(){
      const rows=[...compare].map(id=>institutions.find(item=>item.id===id)).filter(Boolean);
      return `<button class="content-close" type="button" aria-label="${t('close')}">✕</button><div class="modal-panel compare-modal-panel"><div class="sg-eyebrow">${t('compare')}</div><h2>${rows.length?'Сравнение выбранных учреждений':'Добавьте учреждения для сравнения'}</h2>${rows.length?`<div class="compare-grid">${rows.map(item=>`<article><img src="${item.image}" alt="${htmlSafe(nameOf(item.name))}"><h3>${nameOf(item.name)}</h3><p>${t(item.type)} · ${nameOf(item.city)}</p><ul><li>${t('tuitionFrom')}: <b>${item.tuition?formatMoney(item.tuition):t('toConfirm')}</b></li><li>${t('programsWord')}: <b>${item.programCount||t('toConfirm')}</b></li><li>${t('ageFrom')}: <b>${item.minAge?item.minAge+'+':t('byProgram')}</b></li><li>${t('deadline')}: <b>${item.deadline?formatDate(item.deadline):t('toConfirm')}</b></li></ul><button data-detail-from-compare="${item.id}" type="button">${t('details')} ↗</button></article>`).join('')}</div>`:`<p>Нажмите «Сравнить» на двух или трёх карточках каталога. Здесь появятся условия, сроки и программы рядом.</p><a class="consult-submit modal-link-button" href="#catalog">Открыть каталог</a>`}</div>`;
    }
    function openCompare(){
      openContent(compareMarkup(),{type:'compare'});
      $$('#contentModal [data-detail-from-compare]').forEach(button=>button.addEventListener('click',()=>{closeContent();openDetail(button.dataset.detailFromCompare)}));
      $('#contentModal .modal-link-button')?.addEventListener('click',closeContent);
    }
    function favoritesMarkup(){
      const rows=[...favorites].map(id=>institutions.find(item=>item.id===id)).filter(Boolean);
      return `<button class="content-close" type="button" aria-label="${t('close')}">✕</button><div class="modal-panel compare-modal-panel"><div class="sg-eyebrow">${t('favorites')}</div><h2>${rows.length?'Сохранённые учебные заведения':'В избранном пока пусто'}</h2>${rows.length?`<div class="favorite-list">${rows.map(item=>`<button data-detail-from-favorite="${item.id}" type="button"><img src="${item.image}" alt=""><span><strong>${nameOf(item.name)}</strong><small>${t(item.type)} · ${nameOf(item.city)}</small></span><i>↗</i></button>`).join('')}</div>`:'<p>Добавляйте карточки сердечком — список сохранится на этом устройстве.</p>'}</div>`;
    }
    function openFavorites(){
      openContent(favoritesMarkup(),{type:'favorites'});
      $$('#contentModal [data-detail-from-favorite]').forEach(button=>button.addEventListener('click',()=>{closeContent();openDetail(button.dataset.detailFromFavorite)}));
    }


    function syncModalBody(){
      const anyOpen=$('#detailOverlay').classList.contains('show')||$('#contentOverlay').classList.contains('show');
      document.body.classList.toggle('modal-open',anyOpen);
    }
    function openContent(htmlContent,stateInfo){
      contentState=stateInfo||null;
      $('#contentModal').innerHTML=htmlContent;
      $('#contentOverlay').classList.add('show');
      $('#contentOverlay').setAttribute('aria-hidden','false');
      $('#contentOverlay').scrollTop=0;
      syncModalBody();
      const close=$('#contentModal .content-close');if(close)close.addEventListener('click',closeContent);
    }
    function closeContent(){
      $('#contentOverlay').classList.remove('show');
      $('#contentOverlay').setAttribute('aria-hidden','true');
      $('#contentModal').innerHTML='';
      contentState=null;
      syncModalBody();
    }
    function articleMarkup(id){
      const record=ARTICLE_DATA[id];if(!record)return'';
      const a=record[state.lang]||record.ru;
      return `<button class="content-close" type="button" aria-label="${t('close')}">✕</button>
      <header class="article-head"><span class="sg-blog-meta">${a.category}</span><h2>${a.title}</h2><p>${a.lead}</p></header>
      <div class="article-body">
        ${a.facts?`<div class="route-guide-factgrid">${a.facts.map((x,i)=>{const parts=x.split(':');return `<div class="route-guide-fact"><b>${parts.shift()}</b><span>${parts.join(':').trim()}</span></div>`}).join('')}</div>`:''}
        ${a.sections.map(s=>`<section><h3>${s.h}</h3>${s.p.map(p=>`<p>${p}</p>`).join('')}</section>`).join('')}
        <ul class="article-checklist">${a.check.map(x=>`<li>${x}</li>`).join('')}</ul>
        <div class="article-note"><strong>${t('articleImportant')}:</strong> ${a.note}</div>
        ${record.route?`<button class="route-guide-cta" data-route-apply="${record.route}" type="button">${t('showMatchingPrograms')} ↗</button>`:''}
        <div class="article-sources"><h4>${t('articleSources')}</h4><div class="article-source-list">${record.sources.map(s=>`<a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.label} ↗</a>`).join('')}</div></div>
      </div>`;
    }
    function applyRouteSelection(route){
      resetFilters();
      if(route==='language') state.levels=['languageCourse'];
      if(route==='grade9') state.education='grade9';
      if(route==='grade11'){state.education='grade11';state.levels=['foundation','bachelor'];}
      if(route==='master'){state.education='bachelorDegree';state.levels=['master'];}
      if(route==='secondDegree') state.education='bachelorDegree';
      buildFilters();renderCatalog();closeContent();$('#catalog').scrollIntoView({behavior:'smooth'});
    }
    function openArticle(id){
      if(!ARTICLE_DATA[id])return;
      openContent(articleMarkup(id),{type:'article',id});
      const cta=$('#contentModal [data-route-apply]');
      if(cta)cta.addEventListener('click',()=>applyRouteSelection(cta.dataset.routeApply));
    }
    function consultMarkup(){
      return `<button class="content-close" type="button" aria-label="${t('close')}">✕</button>
      <div class="modal-panel"><div class="sg-eyebrow">${t('freeConsultation')}</div><h2>${t('consultModalTitle')}</h2><p>${t('consultModalText')}</p>
      <form class="consult-form" id="consultForm">
        <label>${t('formName')}<input name="name" required autocomplete="name"></label>
        <label>${t('formContact')}<input name="contact" required autocomplete="tel"></label>
        <label class="full">${t('formRoute')}<select name="route"><option>${t('routeLanguageTitle')}</option><option>${t('routeGrade9Title')}</option><option>${t('routeGrade11Title')}</option><option>${t('routeMasterTitle')}</option><option>${t('routeSecondTitle')}</option></select></label>
        <label class="full">${t('formComment')}<textarea name="comment"></textarea></label>
        <button class="consult-submit" type="submit">${t('formSubmit')}</button>
      </form></div>`;
    }
    function openConsult(){
      openContent(consultMarkup(),{type:'consult'});
      const seed=($('#heroConsultInput')?.value||'').trim();
      if(seed){
        const nameField=$('#consultForm [name="name"]');
        const contactField=$('#consultForm [name="contact"]');
        if(seed.includes('@')||/\d/.test(seed)){ if(contactField && !contactField.value) contactField.value=seed; }
        else if(nameField && !nameField.value) nameField.value=seed;
      }
      $('#consultForm').addEventListener('submit',e=>{e.preventDefault();e.currentTarget.innerHTML=`<div class="login-card full"><div class="login-card-icon">✓</div><div><h3>${t('formSuccess')}</h3><p>${t('consultModalText')}</p></div></div>`});
    }
    function loginMarkup(){
      return `<button class="content-close" type="button" aria-label="${t('close')}">✕</button><div class="modal-panel">
      <div class="sg-eyebrow">${t('accountSoon')}</div><h2>${t('accountTitle')}</h2><p>${t('accountText')}</p>
      <div class="login-card"><div class="login-card-icon">◎</div><div><h3>StudyGo ID</h3><p>${t('accountText')}</p></div></div></div>`;
    }
    function openLogin(){openContent(loginMarkup(),{type:'login'})}
    function rerenderContent(){
      if(!contentState)return;
      if(contentState.type==='article')openArticle(contentState.id);
      if(contentState.type==='compare')openCompare();
      if(contentState.type==='favorites')openFavorites();
      if(contentState.type==='program'){
        const institution=institutions.find(item=>item.id===contentState.institutionId);
        if(institution)openProgram(institution,contentState.index);
      }
      if(contentState.type==='consult')openContent(consultMarkup(),contentState);
      if(contentState.type==='login')openContent(loginMarkup(),contentState);
      if(contentState.type==='consult'){const f=$('#consultForm');if(f)f.addEventListener('submit',e=>{e.preventDefault();e.currentTarget.innerHTML=`<div class="login-card full"><div class="login-card-icon">✓</div><div><h3>${t('formSuccess')}</h3><p>${t('consultModalText')}</p></div></div>`})}
    }

    setupLanguageDropdown();
    $('#catalogSearch').addEventListener('input',e=>{state.query=e.target.value;const hs=$('#heroSearch');if(hs)hs.value=e.target.value;state.page=1;renderCatalog()});
    const heroSearchEl=$('#heroSearch');
    if(heroSearchEl){
      heroSearchEl.addEventListener('input',e=>{state.query=e.target.value;$('#catalogSearch').value=e.target.value});
      heroSearchEl.addEventListener('keydown',e=>{if(e.key==='Enter'){state.query=heroSearchEl.value;$('#catalogSearch').value=state.query;renderCatalog();$('#catalog').scrollIntoView({behavior:'smooth'})}});
    }
    $('#sortSelect').addEventListener('change',e=>{state.sort=e.target.value;state.page=1;renderCatalog()});
    $$('[data-quick]').forEach(b=>b.addEventListener('click',()=>{resetFilters();const k=b.dataset.quick;if(k==='grade9')state.education='grade9';if(k==='noHsk')state.hsk='noHsk';if(k==='scholarship')state.scholarship=true;if(k==='english')state.languages=['english'];buildFilters();renderCatalog();$('#catalog').scrollIntoView({behavior:'smooth'})}));
    $$('[data-action="consult"]').forEach(b=>b.addEventListener('click',openConsult));
    $$('#heroFindRouteBtn,[data-action="find-route"]').forEach(b=>b.addEventListener('click',()=>document.getElementById('routes')?.scrollIntoView({behavior:'smooth',block:'start'})));
    $$('[data-action="login"]').forEach(b=>b.addEventListener('click',openLogin));
    $$('[data-article-open]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();openArticle(b.dataset.articleOpen)}));
    $$('.sg-blog-card[data-article]').forEach(card=>{
      card.addEventListener('click',()=>openArticle(card.dataset.article));
      card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openArticle(card.dataset.article)}});
    });
    $$('[data-action="favorites"]').forEach(b=>b.addEventListener('click',openFavorites));
    $$('[data-action="compare-open"]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();openCompare()}));
    $$('[data-action="reset"]').forEach(b=>b.addEventListener('click',resetFilters));
    $('#openFilters').addEventListener('click',()=>$('#drawerBackdrop').classList.add('show'));
    $('#closeFilters').addEventListener('click',()=>$('#drawerBackdrop').classList.remove('show'));
    $('#applyMobile').addEventListener('click',()=>{$('#drawerBackdrop').classList.remove('show');$('#catalog').scrollIntoView({behavior:'smooth'})});
    $('#drawerBackdrop').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.classList.remove('show')});
    $('#detailOverlay').addEventListener('click',e=>{if(e.target===e.currentTarget)closeDetail()});
    $('#contentOverlay').addEventListener('click',e=>{if(e.target===e.currentTarget)closeContent()});
    document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeContent();closeDetail();$('#drawerBackdrop').classList.remove('show')}});
    $('#compareOpen').addEventListener('click',openCompare);


    // Route cards open factual guides; each guide keeps a CTA to the filtered catalogue.
    const ROUTE_ARTICLE_MAP={language:'routeLanguage',grade9:'routeGrade9',grade11:'routeGrade11',master:'routeMaster',secondDegree:'routeSecond'};
    $$('[data-route]').forEach(card=>card.addEventListener('click',()=>openArticle(ROUTE_ARTICLE_MAP[card.dataset.route])));
    const aboutImage=$('#aboutImage'), heroImage=$('.sg-ref-photo-main img');
    if(aboutImage&&heroImage) aboutImage.src=heroImage.src;
    hydrateRouteImages();

    const sgMenu=$('#sgMenuButton'), sgNav=$('#sgMainNav');
    const navDropdowns=$$('.sg-nav-dropdown');
    const closeDropdowns=()=>navDropdowns.forEach(dropdown=>{dropdown.classList.remove('open');dropdown.querySelector('.sg-nav-dropdown-trigger')?.setAttribute('aria-expanded','false')});
    const closeMobileNav=()=>{if(sgNav)sgNav.classList.remove('open');if(sgMenu){sgMenu.setAttribute('aria-expanded','false');sgMenu.textContent='☰'};closeDropdowns()};
    if(sgMenu&&sgNav){
      sgMenu.onclick=e=>{e.preventDefault();e.stopPropagation();const open=!sgNav.classList.contains('open');sgNav.classList.toggle('open',open);sgMenu.setAttribute('aria-expanded',String(open));sgMenu.textContent=open?'✕':'☰'};
      $$('#sgMainNav a').forEach(a=>a.addEventListener('click',closeMobileNav));
    }
    navDropdowns.forEach(dropdown=>{
      const trigger=dropdown.querySelector('.sg-nav-dropdown-trigger');
      if(!trigger)return;
      trigger.addEventListener('click',e=>{
        e.preventDefault();e.stopPropagation();
        const open=!dropdown.classList.contains('open');
        closeDropdowns();
        dropdown.classList.toggle('open',open);
        trigger.setAttribute('aria-expanded',String(open));
      });
    });
    document.addEventListener('click',e=>{if(!e.target.closest('.sg-nav-dropdown'))closeDropdowns();if(sgNav&&sgMenu&&window.innerWidth<=1120&&!sgNav.contains(e.target)&&!sgMenu.contains(e.target))closeMobileNav()});

    document.addEventListener('click',e=>{const consult=e.target.closest('[data-action="consult"]');if(consult&&!consult.closest('#detailShell')&&!consult.closest('#contentModal')){e.preventDefault();openConsult()}});

    buildFilters();buildSort();applyTranslations();
    // The catalogue is rendered after the browser's first hash calculation.
    // Re-apply a direct section link once the final layout is in place.
    if(location.hash){
      requestAnimationFrame(()=>requestAnimationFrame(()=>{
        const target=document.querySelector(location.hash);
        if(target)target.scrollIntoView({block:'start'});
      }));
    }
